import asynciofrom typing import Dict, Any, Literalfrom langgraph.graph import StateGraph, START, ENDfrom langgraph.prebuilt import ToolExecutor, ToolInvocationfrom src.graph.state import AgentStatefrom src.agents import (    HornyDetectorAgent,    IntentionDetectorAgent,    MediaTaggerAgent,    RecommenderAgent,    ChatGeneratorAgent,    ViolationDetectorAgent,    HallucinationDetectorAgent,    ProfileSummarizerAgent)from src.nodes import (    InputValidatorNode,    ContextBuilderNode,    HistoryProcessorNode,    ActionRouterNode,    QualityAssuranceNode,    ResponseFormatterNode)from src.tools import (    ApiClientTool,    ContentSearchTool,    HistoryTool)class ChatWorkflow:    """聊天机器人工作流定义"""    def __init__(self):        self.horny_detector = HornyDetectorAgent()        self.intention_detector = IntentionDetectorAgent()        self.media_tagger = MediaTaggerAgent()        self.recommender = RecommenderAgent()        self.chat_generator = ChatGeneratorAgent()        self.violation_detector = ViolationDetectorAgent()        self.hallucination_detector = HallucinationDetectorAgent()        self.profile_summarizer = ProfileSummarizerAgent()        # 工具        self.api_client_tool = ApiClientTool()        self.content_search_tool = ContentSearchTool()        self.history_tool = HistoryTool()        # 节点        self.input_validator = InputValidatorNode()        self.context_builder = ContextBuilderNode()        self.history_processor = HistoryProcessorNode()        self.action_router = ActionRouterNode()        self.quality_assurance = QualityAssuranceNode()        self.response_formatter = ResponseFormatterNode()        self.tool_executor = ToolExecutor([            self.api_client_tool,            self.content_search_tool,            self.history_tool        ])        self.workflow = self._build_graph()    def _build_graph(self) -> StateGraph:        """构建工作流图"""        workflow = StateGraph(AgentState)        # 添加节点        workflow.add_node("input_validation", self.input_validator.run)        workflow.add_node("context_building", self.context_builder.run)        workflow.add_node("history_processing", self.history_processor.run)        workflow.add_node("horny_detection", self.horny_detector.run)        workflow.add_node("faq_matching", self.faq_matcher.run)  # 新增：FAQ匹配节点        workflow.add_node("intention_detection", self.intention_detector.run)        workflow.add_node("media_tagging", self.media_tagger.run)        workflow.add_node("recommendation", self.recommender.run)        workflow.add_node("chat_generation", self.chat_generator.run)        workflow.add_node("quality_assurance", self.quality_assurance.run)        workflow.add_node("action_routing", self.action_router.run)        workflow.add_node("response_formatting", self.response_formatter.run)        workflow.add_node("profile_summarization", self.profile_summarizer.run)        # 添加边        workflow.add_edge(START, "input_validation")        workflow.add_edge("input_validation", "context_building")        workflow.add_edge("context_building", "history_processing")        workflow.add_edge("history_processing", "horny_detection")        workflow.add_edge("horny_detection", "action_routing")        # 调整action_routing后的路由：先走FAQ匹配（对应原use_faq逻辑）        workflow.add_conditional_edges(            "action_routing",            self._route_by_scene,            {                "faq_flow": "faq_matching",  # 新增：FAQ流程先匹配FAQ                "chat_flow": "faq_matching",  # 新增：普通聊天先匹配FAQ                "activate_flow": "chat_generation",  # 激活流程直接走LLM                "follow_up_flow": "chat_generation",  # 跟进流程直接走LLM                "profile_summary_flow": "profile_summarization"            }        )        # ========== 3. 新增FAQ匹配后的分支（核心映射原use_faq逻辑） ==========        workflow.add_conditional_edges(            "faq_matching",            self._route_by_faq_result,  # 新增：根据FAQ匹配结果路由            {                "faq_hit": "chat_generation",  # 匹配到FAQ → 直接用FAQ结果生成回复                "faq_miss": "intention_detection"  # 未匹配到FAQ → 走意图检测            }        )        # 意图检测后的分支        workflow.add_conditional_edges(            "intention_detection",            self._route_by_intention,            {                "content_request": "media_tagging",                "ready_to_purchase": "media_tagging",                "other": "chat_generation",                "ppv_refuse": "chat_generation"            }        )        workflow.add_edge("media_tagging", "recommendation")        workflow.add_edge("recommendation", "chat_generation")        workflow.add_edge("profile_summarization", "response_formatting")        # 质量保证循环        workflow.add_edge("chat_generation", "quality_assurance")        workflow.add_conditional_edges(            "quality_assurance",            self._route_by_quality_check,            {                "regenerate": "chat_generation",                "proceed": "response_formatting"            }        )        workflow.add_edge("response_formatting", END)        return workflow    def _route_by_scene(self, state: AgentState) -> str:        """根据场景路由"""        if state.scene == "activate":            return "activate_flow"        elif state.scene == "follow_up":            return "follow_up_flow"        elif state.business_info.input_interrupted and state.business_info.interrupted_reason != "Cancel hosting interruption":            return "profile_summary_flow"        elif state.scene == "chat" and not state.business_info.input_interrupted:            return "faq_flow"  # 新增：普通聊天且未中断 → 走FAQ流程        else:            return "chat_flow"    def _route_by_faq_result(self, state: AgentState) -> str:        """新增：根据FAQ匹配结果路由（对应原use_faq逻辑）"""        # 核心逻辑：state中存储FAQ匹配结果（由faq_matcher.run设置）        # 匹配到FAQ → faq_hit，否则 → faq_miss        if hasattr(state, "faq_matched") and state.faq_matched:            return "faq_hit"        else:            return "faq_miss"    def _route_by_intention(self, state: AgentState) -> str:        """根据意图路由"""        action = state.dialog_state.action        if action == "fan_intention_content_request":            return "content_request"        elif action == "fan_intention_ready_to_purchase":            return "ready_to_purchase"        elif action == "ppv_request_refuse":            return "ppv_refuse"        else:            return "other"    def _route_by_quality_check(self, state: AgentState) -> str:        """根据质量检查结果路由"""        if state.should_regenerate:            return "regenerate"        else:            return "proceed"    def compile(self):        """编译工作流"""        return self.workflow.compile()    async def run(self, initial_state: AgentState) -> AgentState:        """运行工作流"""        app = self.compile()        result = await app.ainvoke(initial_state)        return result